package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

/**
 * Derives the membership scoring for an owner. {@link #points} starts at 0 and adds 2
 * when an email address is present, 1 when namesakeCount is 0, 2 for a household of 3 or
 * more (the new owner plus namesakeCount existing members) and 3 for tenure of at least one
 * elapsed {@link FiscalYear} between registrationDate and today. {@link #level} maps those
 * points to 1 (0-1),
 * 2 (2-3), 3 (4-5) or 4 (6 or more).
 */
public final class MembershipTier {

    private MembershipTier() {
    }

    private static boolean hasTenure(LocalDate registrationDate) {
        return registrationDate != null
                && FiscalYear.elapsed(registrationDate, LocalDate.now()) > 0;
    }

    public static int points(Integer namesakeCount, String email, LocalDate registrationDate) {
        int points = 0;
        if (email != null && !email.isBlank()) {
            points += 2;
        }
        if (namesakeCount != null && namesakeCount == 0) {
            points += 1;
        }
        if (namesakeCount != null && namesakeCount >= 2) {
            points += 2;
        }
        if (hasTenure(registrationDate)) {
            points += 3;
        }
        return points;
    }

    public static int level(int points) {
        if (points >= 6) {
            return 4;
        }
        if (points >= 4) {
            return 3;
        }
        if (points >= 2) {
            return 2;
        }
        return 1;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the stable {@code householdId} shared by owners with the same lastName and
 * postcode. It is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, where the lastName is compared
 * case-insensitively with collapsed whitespace, so co-resident same-lastName owners always
 * resolve to one identifier.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalise(lastName) + '|' + (postcode == null ? "" : postcode);
        return sha256Hex(key).substring(0, 12);
    }

    private static String normalise(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

